// 이 함수는 그대로 두세요
async function count(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('불러오지 못했습니다 (' + res.status + ')');
  }
  const list = await res.json();
  return list.length;
}

async function collect(urls) {
  const results = await Promise.allSettled(urls.map((url) => count(url)));

  return {
    counts: results.filter((r) => r.status === 'fulfilled').map((r) => r.value),
    errors: results.filter((r) => r.status === 'rejected').map((r) => r.reason.message),
  };
}
